<div class="columns"><section class="card"><h2>Production step templates</h2><p class="muted">Templates are available for future workflows. Renaming or disabling a template leaves saved item steps intact.</p><?php foreach(rows('SELECT * FROM step_templates ORDER BY position,id') as $t): ?><details><summary><?=e($t['position'].' · '.$t['name'])?><span><?=$t['active']?'Active':'Disabled'?></span></summary><?php template_form($t); ?></details><?php endforeach ?><details><summary>+ New template</summary><?php template_form(($_POST['action']??'')==='template'&&isset($error)?$_POST:[]); ?></details></section>
<section class="card"><h2>Component types</h2><div class="chips"><?php foreach(rows('SELECT * FROM component_types ORDER BY name') as $t): ?><span class="badge"><?=e($t['name'])?></span><?php endforeach ?></div><?php startform('component_type');field('Custom component type','name',($_POST['action']??'')==='component_type'?($_POST['name']??''):'','text',true,'maxlength="100"'); ?><button>Add type</button></form><h3>AI configuration</h3><p class="muted">AI is <?=!empty($config['ai']['key'])&&!empty($config['ai']['model'])?'configured':'disabled'?>. Use the AI setup form below to enter a key and model. Secrets are never sent to the browser.</p></section></div>
<section class="card" id="ai-setup"><h2>AI setup</h2><p class="muted">Enter your own OpenAI API key and a model ID available in your API account that supports images and PDFs. API billing is separate from ChatGPT. All staff in this MVP can change these settings. The saved key is kept privately on this PC and is never shown in the form.</p>
<?php startform('ai_settings');field(!empty($config['ai']['key'])?'New API key (leave blank to keep saved key)':'API key','api_key','','password',empty($config['ai']['key']),'autocomplete="new-password" maxlength="512"');field('Model ID','model',($_POST['action']??'')==='ai_settings'?($_POST['model']??''):($config['ai']['model']??''),'text',true,'maxlength="100"'); ?><button>Save AI settings</button></form></section>
<?php function template_form(array $t):void{startform('template',['id'=>$t['id']??'']);field('Name','name',$t['name']??'','text',true,'maxlength="100"');field('Position','position',$t['position']??10,'number',true,'min="0" max="9999"');echo '<label class="check"><input type="checkbox" name="active" '.(($t['active']??1)?'checked':'').'>Active</label><button>Save template</button></form>';} ?>
